21	export class ContextManager {
22	  private readonly loadedPaths: Set<string> = new Set();
23	  private readonly loadedFileIdentities: Set<string> = new Set();
24	  private readonly config: Config;
25	  private globalMemory: string = '';
26	  private extensionMemory: string = '';
27	  private projectMemory: string = '';
28	
29	  constructor(config: Config) {
30	    this.config = config;
31	  }
32	
33	  /**
34	   * Refreshes the memory by reloading global, extension, and project memory.
35	   */
36	  async refresh(): Promise<void> {
37	    this.loadedPaths.clear();
38	    this.loadedFileIdentities.clear();
39	
40	    const paths = await this.discoverMemoryPaths();
41	    const contentsMap = await this.loadMemoryContents(paths);
42	
43	    this.categorizeMemoryContents(paths, contentsMap);
44	    this.emitMemoryChanged();
45	  }
46	
47	  private async discoverMemoryPaths() {
48	    const [global, extension, project] = await Promise.all([
49	      getGlobalMemoryPaths(),
50	      Promise.resolve(
51	        getExtensionMemoryPaths(this.config.getExtensionLoader()),
52	      ),
53	      this.config.isTrustedFolder()
54	        ? getEnvironmentMemoryPaths([
55	            ...this.config.getWorkspaceContext().getDirectories(),
56	          ])
57	        : Promise.resolve([]),
58	    ]);
59	
60	    return { global, extension, project };
61	  }
62	
63	  private async loadMemoryContents(paths: {
64	    global: string[];
65	    extension: string[];
66	    project: string[];
67	  }) {
68	    const allPathsStringDeduped = Array.from(
69	      new Set([...paths.global, ...paths.extension, ...paths.project]),
70	    );
71	
72	    // deduplicate by file identity to handle case-insensitive filesystems
73	    const { paths: allPaths, identityMap: pathIdentityMap } =
74	      await deduplicatePathsByFileIdentity(allPathsStringDeduped);
75	
76	    const allContents = await readGeminiMdFiles(
77	      allPaths,
78	      this.config.getImportFormat(),
79	    );
80	
81	    const loadedFilePaths = allContents
82	      .filter((c) => c.content !== null)
83	      .map((c) => c.filePath);
84	    this.markAsLoaded(loadedFilePaths);
85	
86	    // Cache file identities for performance optimization
87	    for (const filePath of loadedFilePaths) {
88	      const identity = pathIdentityMap.get(filePath);
89	      if (identity) {
90	        this.loadedFileIdentities.add(identity);
91	      }
92	    }
93	
94	    return new Map(allContents.map((c) => [c.filePath, c]));
95	  }
96	
97	  private categorizeMemoryContents(
98	    paths: { global: string[]; extension: string[]; project: string[] },
99	    contentsMap: Map<string, GeminiFileContent>,
100	  ) {
101	    const workingDir = this.config.getWorkingDir();
102	    const hierarchicalMemory = categorizeAndConcatenate(
103	      paths,
104	      contentsMap,
105	      workingDir,
106	    );
107	
108	    this.globalMemory = hierarchicalMemory.global || '';
109	    this.extensionMemory = hierarchicalMemory.extension || '';
110	
111	    const mcpInstructions =
112	      this.config.getMcpClientManager()?.getMcpInstructions() || '';
113	    const projectMemoryWithMcp = [
114	      hierarchicalMemory.project,
115	      mcpInstructions.trimStart(),
116	    ]
117	      .filter(Boolean)
118	      .join('\n\n');
119	
120	    this.projectMemory = this.config.isTrustedFolder()
121	      ? projectMemoryWithMcp
122	      : '';
123	  }
124	
125	  /**
126	   * Discovers and loads context for a specific accessed path (Tier 3 - JIT).
127	   * Traverses upwards from the accessed path to the project root.
128	   */
129	  async discoverContext(
130	    accessedPath: string,
131	    trustedRoots: string[],
132	  ): Promise<string> {
133	    if (!this.config.isTrustedFolder()) {
134	      return '';
135	    }
136	    const result = await loadJitSubdirectoryMemory(
137	      accessedPath,
138	      trustedRoots,
139	      this.loadedPaths,
140	      this.loadedFileIdentities,
141	    );
142	
143	    if (result.files.length === 0) {
144	      return '';
145	    }
146	
147	    const newFilePaths = result.files.map((f) => f.path);
148	    this.markAsLoaded(newFilePaths);
149	
150	    // Cache identities for newly loaded files
151	    if (result.fileIdentities) {
152	      for (const identity of result.fileIdentities) {
153	        this.loadedFileIdentities.add(identity);
154	      }
155	    }
156	    return concatenateInstructions(
157	      result.files.map((f) => ({ filePath: f.path, content: f.content })),
158	      this.config.getWorkingDir(),
159	    );
160	  }
161	
162	  private emitMemoryChanged(): void {
163	    coreEvents.emit(CoreEvent.MemoryChanged, {
164	      fileCount: this.loadedPaths.size,
165	    });
166	  }
167	
168	  getGlobalMemory(): string {
169	    return this.globalMemory;
170	  }
171	
172	  getExtensionMemory(): string {
173	    return this.extensionMemory;
174	  }
175	
176	  getEnvironmentMemory(): string {
177	    return this.projectMemory;
178	  }
179	
180	  private markAsLoaded(paths: string[]): void {
181	    paths.forEach((p) => this.loadedPaths.add(p));
182	  }
183	
184	  getLoadedPaths(): ReadonlySet<string> {
185	    return this.loadedPaths;
186	  }
187	}
